local MoldCoatingRollerMaker = {}
local PRODUCTS = {
    iron_moldcoatingroller = { name = "Železni valj za premaze kalupov", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni valj za premaze kalupov za livarje." },
    bronze_moldcoatingroller = { name = "Bronast valj za premaze kalupov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast valj za premaze kalupov za livarje." },
    silver_moldcoatingroller = { name = "Srebrn valj za premaze kalupov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn valj za premaze kalupov za livarje." },
    gilded_moldcoatingroller = { name = "Pozlačen valj za premaze kalupov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen valj za premaze kalupov za livarje." },
    jewel_set_moldcoatingroller = { name = "Draguljast valj za premaze kalupov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast valj za premaze kalupov za livarje." },
    royal_sovereign_moldcoatingroller = { name = "Kraljevski suveren valj za premaze kalupov", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren valj za premaze kalupov z biseri za krono." },
}
local BUILDINGS = {
    moldcoatingroller_workshop = { name = "Moldcoatingroller delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    moldcoatingroller_house = { name = "Moldcoatingroller hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_moldcoatingroller_atelier = { name = "Mojstrski moldcoatingroller atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_moldcoatingroller_palace = { name = "Suverena moldcoatingroller palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MoldCoatingRollerMaker.ironStock=16; MoldCoatingRollerMaker.bronzeStock=12; MoldCoatingRollerMaker.woodStock=14; MoldCoatingRollerMaker.leatherStock=8; MoldCoatingRollerMaker.silverStock=8; MoldCoatingRollerMaker.goldStock=6; MoldCoatingRollerMaker.jewelStock=4; MoldCoatingRollerMaker.pearlStock=4
MoldCoatingRollerMaker.productStock = {}; MoldCoatingRollerMaker.buildings = {}; MoldCoatingRollerMaker.maker = nil; MoldCoatingRollerMaker.activeMaking = {}; MoldCoatingRollerMaker.totalProducts = 0; MoldCoatingRollerMaker.dayTimer = 0
function MoldCoatingRollerMaker.init() MoldCoatingRollerMaker.ironStock=16; MoldCoatingRollerMaker.bronzeStock=12; MoldCoatingRollerMaker.woodStock=14; MoldCoatingRollerMaker.leatherStock=8; MoldCoatingRollerMaker.silverStock=8; MoldCoatingRollerMaker.goldStock=6; MoldCoatingRollerMaker.jewelStock=4; MoldCoatingRollerMaker.pearlStock=4; MoldCoatingRollerMaker.productStock={}; MoldCoatingRollerMaker.buildings={}; MoldCoatingRollerMaker.maker=nil; MoldCoatingRollerMaker.activeMaking={}; MoldCoatingRollerMaker.totalProducts=0; MoldCoatingRollerMaker.dayTimer=0; print("[MoldCoatingRollerMaker] Royal Mold Coating Roller Maker System initialized (6 products, 4 buildings)") end
function MoldCoatingRollerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MoldCoatingRollerMaker.maker={name=n or ("Valjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjar najet: %s (spretnost: %d)",MoldCoatingRollerMaker.maker.name,s),"success") end; return true end
function MoldCoatingRollerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MoldCoatingRollerMaker.build(id) local ok,e=MoldCoatingRollerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MoldCoatingRollerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MoldCoatingRollerMaker.getQualityBonus() local b=0; for _,bd in ipairs(MoldCoatingRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MoldCoatingRollerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MoldCoatingRollerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MoldCoatingRollerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MoldCoatingRollerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MoldCoatingRollerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MoldCoatingRollerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MoldCoatingRollerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MoldCoatingRollerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MoldCoatingRollerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MoldCoatingRollerMaker.buildings==0 then return false,"Potrebna valjarna delavnica" end; if not MoldCoatingRollerMaker.maker then return false,"Potreben valjar" end; return true end
function MoldCoatingRollerMaker.make(pt,qty) qty=qty or 1; local ok,e=MoldCoatingRollerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MoldCoatingRollerMaker.ironStock=MoldCoatingRollerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MoldCoatingRollerMaker.bronzeStock=MoldCoatingRollerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MoldCoatingRollerMaker.woodStock=MoldCoatingRollerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MoldCoatingRollerMaker.leatherStock=MoldCoatingRollerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MoldCoatingRollerMaker.silverStock=MoldCoatingRollerMaker.silverStock-d.silverCost*qty end; if d.goldCost then MoldCoatingRollerMaker.goldStock=MoldCoatingRollerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MoldCoatingRollerMaker.jewelStock=MoldCoatingRollerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MoldCoatingRollerMaker.pearlStock=MoldCoatingRollerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MoldCoatingRollerMaker.maker then t=math.max(1,t-math.floor(MoldCoatingRollerMaker.maker.skill/13)) end; table.insert(MoldCoatingRollerMaker.activeMaking,{id="moldcoatingroller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MoldCoatingRollerMaker.completeMaking(m) local q=1.0+(MoldCoatingRollerMaker.getQualityBonus()/100); if MoldCoatingRollerMaker.maker then q=q+(MoldCoatingRollerMaker.maker.skill/140) end; q=math.min(2.5,q); MoldCoatingRollerMaker.productStock[m.productType]=(MoldCoatingRollerMaker.productStock[m.productType] or 0)+m.quantity; MoldCoatingRollerMaker.totalProducts=MoldCoatingRollerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldCoatingRollerMaker.maker then MoldCoatingRollerMaker.maker.itemsMade=MoldCoatingRollerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldCoatingRollerMaker.maker.skill=math.min(100,MoldCoatingRollerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"moldcoatingroller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MoldCoatingRollerMaker.update(dt) if not _G.state then return end; MoldCoatingRollerMaker.dayTimer=MoldCoatingRollerMaker.dayTimer+dt; if MoldCoatingRollerMaker.dayTimer>=30 then MoldCoatingRollerMaker.dayTimer=0; for i=#MoldCoatingRollerMaker.activeMaking,1,-1 do local m=MoldCoatingRollerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MoldCoatingRollerMaker.completeMaking(m); table.remove(MoldCoatingRollerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MoldCoatingRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MoldCoatingRollerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MoldCoatingRollerMaker.getStats() return {ironStock=MoldCoatingRollerMaker.ironStock,bronzeStock=MoldCoatingRollerMaker.bronzeStock,woodStock=MoldCoatingRollerMaker.woodStock,leatherStock=MoldCoatingRollerMaker.leatherStock,silverStock=MoldCoatingRollerMaker.silverStock,goldStock=MoldCoatingRollerMaker.goldStock,jewelStock=MoldCoatingRollerMaker.jewelStock,pearlStock=MoldCoatingRollerMaker.pearlStock,productStock=MoldCoatingRollerMaker.productStock,numBuildings=#MoldCoatingRollerMaker.buildings,hasMaker=MoldCoatingRollerMaker.maker~=nil,makerName=MoldCoatingRollerMaker.maker and MoldCoatingRollerMaker.maker.name or "—",makerSkill=MoldCoatingRollerMaker.maker and MoldCoatingRollerMaker.maker.skill or 0,activeMaking=#MoldCoatingRollerMaker.activeMaking,totalProducts=MoldCoatingRollerMaker.totalProducts} end
return MoldCoatingRollerMaker
